(7755548, 1283014, 60862, '<td valign="top">Spectacular view. I would have liked it even better with less of the sky and more of the land at the bottom.</td>', 'Spectacular view. I would have liked it even better with less of the sky and more of the land at the bottom.', '2023-08-02 16:26:11.000000', NULL, 1),
(7755549, 1282755, 60862, '<td valign="top">WOW!</td>', 'WOW!', '2023-08-02 16:28:30.000000', NULL, 1),
