(7755777, 1282755, 65234, '<td valign="top">Great detail..</td>', 'Great detail..', '2023-08-05 17:08:46.000000', NULL, 1),
(7755778, 1283068, 65234, '<td valign="top">Nice detail and catchlight. An ordinary subject well-captured.</td>', 'Nice detail and catchlight. An ordinary subject well-captured.', '2023-08-05 17:09:30.000000', NULL, 1),
(7755779, 1283046, 65234, '<td valign="top">Would love to get a chance to get an image like this! Personally, I would have dodged the catchlights a bit to bring them out more, but that''s a nit.</td>', 'Would love to get a chance to get an image like this! Personally, I would have dodged the catchlights a bit to bring them out more, but that''s a nit.', '2023-08-05 17:11:01.000000', NULL, 1),
(7755780, 1283078, 65234, '<td valign="top">Um, I''m sure someone else has mentioned it, but those are commonly known as hoverflies. Still little itsy bitsy bugs so this is a nice capture.</td>', 'Um, I''m sure someone else has mentioned it, but those are commonly known as hoverflies. Still little itsy bitsy bugs so this is a nice capture.', '2023-08-05 17:12:09.000000', NULL, 1),
(7755789, 1282391, 100831, '<td valign="top">Fabulous... you looking in and her looking out at the scene. The DOF totally makes this shot for me. And your monochrome is perfect. 9</td>', 'Fabulous... you looking in and her looking out at the scene. The DOF totally makes this shot for me. And your monochrome is perfect. 9', '2023-08-05 20:46:40.000000', NULL, 1),
(7755790, 1283097, 100831, '<td valign="top">The deep blacks are terrific. Love that reflection.<br/>If it were mine, I might have tried to balance the % of top and bottom (bit of crop off the top) but it''s not and I''m enjoying it so there you go!</td>', 'The deep blacks are terrific. Love that reflection.If it were mine, I might have tried to balance the % of top and bottom (bit of crop off the top) but it''s not and I''m enjoying it so there you go!', '2023-08-05 20:49:28.000000', NULL, 1),
