(7755803, 1282809, 35086, '<td valign="top">Great timing here.</td>', 'Great timing here.', '2023-08-06 01:55:09.000000', NULL, 1),
(7755817, 1283026, 83313, '<td valign="top">Thag tyred of hunting and killing, so invents cureer as sooper modul. Thag think he only have to stand around luking pritty, but is hard wurk and gets swetty. Thag colapsus on steps during promo for grate invenchun of persunal wings. Grog blame Thag for comershul falure of produkt. Taker of pickchurs shuld have entured this in "falure" challunge insted.</td>', 'Thag tyred of hunting and killing, so invents cureer as sooper modul. Thag think he only have to stand around luking pritty, but is hard wurk and gets swetty. Thag colapsus on steps during promo for grate invenchun of persunal wings. Grog blame Thag for comershul falure of produkt. Taker of pickchurs shuld have entured this in "falure" challunge insted.', '2023-08-06 11:41:32.000000', NULL, 1),
(7755818, 1282968, 83313, '<td valign="top">What an unnerving smile! It is what makes the shot. The slight tilt bothers me, though. I am trying to figure out where the camera is. I''m guessing off to frame right and enough of a crop that... Oh wait. This isn''t a mirror! Ok, extra pointage for confusing me and making me look harder at the details.</td>', 'What an unnerving smile! It is what makes the shot. The slight tilt bothers me, though. I am trying to figure out where the camera is. I''m guessing off to frame right and enough of a crop that... Oh wait. This isn''t a mirror! Ok, extra pointage for confusing me and making me look harder at the details.', '2023-08-06 11:47:10.000000', NULL, 1),
(7755819, 1282391, 83313, '<td valign="top">Strangely captivating. The odd shape around the subject''s head (reflection?) makes me take second and third looks.</td>', 'Strangely captivating. The odd shape around the subject''s head (reflection?) makes me take second and third looks.', '2023-08-06 11:53:33.000000', NULL, 1),
(7755820, 1283073, 83313, '<td valign="top">A bit too centered for my preferences, but amazing to get such a shot at night.</td>', 'A bit too centered for my preferences, but amazing to get such a shot at night.', '2023-08-06 11:57:16.000000', NULL, 1),
(7755873, 1283095, 114285, '<td valign="top">What an absolutely phenomenal image. Instant fave.<br/> <br/>Im guessing its Pennystreets grandson and daughter.</td>', 'What an absolutely phenomenal image. Instant fave. Im guessing its Pennystreets grandson and daughter.', '2023-08-07 08:24:07.000000', NULL, 1),
(7755996, 1282391, 50695, '<td valign="top">Many of the Team Spleen have been zonked by this image ... how dare you look back at us? ... and as a result we have crowned you Queen for a Challenge.<br/> <br/>Here is your Spleen Queen<br/> <br/><a href="https://www.dpchallenge.com/image.php?IMAGE_ID=1282295" rel="nofollow" target="_blank"><img border="0" src="https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1282295.jpg" xalt="'' . substr(''https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1282295.jpg'', strrpos(''https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1282295.jpg'', ''/'') + 1) . ''"/></a> <br/> <br/>huzzah and congratulations!</td>', 'Many of the Team Spleen have been zonked by this image ... how dare you look back at us? ... and as a result we have crowned you Queen for a Challenge. Here is your Spleen Queen   huzzah and congratulations!', '2023-08-07 21:50:55.000000', NULL, 1),
(7755997, 1283042, 50695, '<td valign="top">This is what a photographer does. They stop and take a picture, reveal worlds within worlds, scenes within panes, dreams within moments.<br/> <br/>It is my honor as Team Spleen representative to promote your image to the Court of Spleen in perpetuity.<br/> <br/><a href="https://www.dpchallenge.com/image.php?IMAGE_ID=1156027" rel="nofollow" target="_blank"><img border="0" src="https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg" xalt="'' . substr(''https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg'', strrpos(''https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg'', ''/'') + 1) . ''"/></a></td>', 'This is what a photographer does. They stop and take a picture, reveal worlds within worlds, scenes within panes, dreams within moments. It is my honor as Team Spleen representative to promote your image to the Court of Spleen in perpetuity. ', '2023-08-07 21:54:14.000000', NULL, 1),
(7755998, 1283076, 50695, '<td valign="top">Hear ye, hear ye, <br/> <br/>for the crime of blurring a landscape with foreground,<br/> <br/>for the travesty of creating a map of a fantasy world on what once was the sky,<br/> <br/>for that dread blasphemy on memory and art known as photography,<br/> <br/>your image has been sentenced by the Court to be full of Spleen<br/> <br/><a href="https://www.dpchallenge.com/image.php?IMAGE_ID=1156027" rel="nofollow" target="_blank"><img border="0" src="https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg" xalt="'' . substr(''https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg'', strrpos(''https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg'', ''/'') + 1) . ''"/></a></td>', 'Hear ye, hear ye,  for the crime of blurring a landscape with foreground, for the travesty of creating a map of a fantasy world on what once was the sky, for that dread blasphemy on memory and art known as photography, your image has been sentenced by the Court to be full of Spleen ', '2023-08-07 21:56:27.000000', NULL, 1),
(7756000, 1282964, 50695, '<td valign="top">for this unwavering look at humanity and art, the Team of Spleen has awarded your image to our Court. Congratulations!<br/> <br/><a href="https://www.dpchallenge.com/image.php?IMAGE_ID=1156027" rel="nofollow" target="_blank"><img border="0" src="https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg" xalt="'' . substr(''https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg'', strrpos(''https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg'', ''/'') + 1) . ''"/></a></td>', 'for this unwavering look at humanity and art, the Team of Spleen has awarded your image to our Court. Congratulations! ', '2023-08-07 21:57:49.000000', NULL, 1),
(7756008, 1283071, 50695, '<td valign="top">As to your image being deemed serenely beautiful by certain members of Team Spleen, it is my honor to award you the infamous Spleen Court award.<br/> <br/><a href="https://www.dpchallenge.com/image.php?IMAGE_ID=1156027" rel="nofollow" target="_blank"><img border="0" src="https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg" xalt="'' . substr(''https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg'', strrpos(''https://images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg'', ''/'') + 1) . ''"/></a></td>', 'As to your image being deemed serenely beautiful by certain members of Team Spleen, it is my honor to award you the infamous Spleen Court award. ', '2023-08-07 21:59:46.000000', NULL, 1),
